+ * See the License for the specific language governing permissions and
+ * limitations under the License.
+ */
+
+#include "narrowingConverter.h"
+
+#include "checker/ETSchecker.h"
+#include "ir/expressions/assignmentExpression.h"
+#include "ir/expressions/binaryExpression.h"
+#include "ir/expressions/callExpression.h"
+#include "ir/expressions/identifier.h"
+#include "ir/expressions/literals/numberLiteral.h"
+#include "ir/expressions/memberExpression.h"
+#include "ir/expressions/unaryExpression.h"
+#include "ir/statements/variableDeclarator.h"
+
+#include <cstdint>
+#include <limits>
+#include <optional>
+
+namespace ark::es2panda::checker {
+namespace {
+
+std::optional<int64_t> EvalIntegerConstant(const ir::Expression *expr);
+
+std::optional<int64_t> EvalIntegerLiteral(const ir::NumberLiteral *literal)
+{
+    auto const &number = literal->Number();
+    if (!number.CanGetValue<int64_t>()) {
+        return std::nullopt;
+    }
+
+    return number.GetLong();
+}
+
+std::optional<int64_t> EvalUnaryConstant(const ir::UnaryExpression *expr)
+{
+    auto value = EvalIntegerConstant(expr->Argument());
+    if (!value.has_value()) {
+        return std::nullopt;
+    }
+
+    switch (expr->OperatorType()) {
+        case lexer::TokenType::PUNCTUATOR_PLUS:
+            return value;
+        case lexer::TokenType::PUNCTUATOR_MINUS:
+            if (value.value() == std::numeric_limits<int64_t>::min()) {
+                return std::nullopt;
+            }
+            return -value.value();
+        default:
+            return std::nullopt;
+    }
+}
+
+bool AddOverflow(int64_t a, int64_t b, int64_t *result)
+{
+    *result = static_cast<int64_t>(static_cast<uint64_t>(a) + static_cast<uint64_t>(b));
+    return (b > 0 && a > std::numeric_limits<int64_t>::max() - b) ||
+           (b < 0 && a < std::numeric_limits<int64_t>::min() - b);
+}
+
+bool SubOverflow(int64_t a, int64_t b, int64_t *result)
+{
+    *result = static_cast<int64_t>(static_cast<uint64_t>(a) - static_cast<uint64_t>(b));
+    return (b < 0 && a > std::numeric_limits<int64_t>::max() + b) ||
+           (b > 0 && a < std::numeric_limits<int64_t>::min() + b);
+}
+
+bool MulOverflow(int64_t a, int64_t b, int64_t *result)
+{
+    *result = static_cast<int64_t>(static_cast<uint64_t>(a) * static_cast<uint64_t>(b));
+    if (a == 0 || b == 0) {
+        return false;
+    }
+    if ((a == -1 && b == std::numeric_limits<int64_t>::min()) ||
+        (b == -1 && a == std::numeric_limits<int64_t>::min())) {
+        return true;
+    }
+    return *result / a != b;
+}
+
+std::optional<int64_t> EvalArithmeticOp(int64_t left, int64_t right, lexer::TokenType op)
+{
+    int64_t result = 0;
+
+    switch (op) {
+        case lexer::TokenType::PUNCTUATOR_PLUS:
+            if (AddOverflow(left, right, &result)) {
+                return std::nullopt;
+            }
+            return result;
+        case lexer::TokenType::PUNCTUATOR_MINUS:
+            if (SubOverflow(left, right, &result)) {
+                return std::nullopt;
+            }
+            return result;
+        case lexer::TokenType::PUNCTUATOR_MULTIPLY:
+            if (MulOverflow(left, right, &result)) {
+                return std::nullopt;
+            }
+            return result;
+        case lexer::TokenType::PUNCTUATOR_DIVIDE:
+            if (right == 0 || (left == std::numeric_limits<int64_t>::min() && right == -1)) {
+                return std::nullopt;
+            }
+            return left / right;
+        case lexer::TokenType::PUNCTUATOR_MOD:
+            if (right == 0 || (left == std::numeric_limits<int64_t>::min() && right == -1)) {
+                return std::nullopt;
+            }
+            return left % right;
+        default:
+            return std::nullopt;
+    }
+}
+
+std::optional<int64_t> EvalBinaryConstant(const ir::BinaryExpression *expr)
+{
+    auto left = EvalIntegerConstant(expr->Left());
+    auto right = EvalIntegerConstant(expr->Right());
+    if (!left.has_value() || !right.has_value()) {
+        return std::nullopt;
+    }
+
+    return EvalArithmeticOp(left.value(), right.value(), expr->OperatorType());
+}
+
+bool IsNumericConversion(const util::StringView &name)
+{
+    return name.Is("toByte") || name.Is("toShort") || name.Is("toInt") || name.Is("toLong") || name.Is("toChar");
+}
+
+std::optional<int64_t> EvalConversionCall(const ir::CallExpression *call)
+{
+    if (!call->Arguments().empty() || !call->Callee()->IsMemberExpression()) {
+        return std::nullopt;
+    }
+
+    auto *member = call->Callee()->AsMemberExpression();
+    if (!member->Property()->IsIdentifier()) {
+        return std::nullopt;
+    }
+    auto *objectType = member->Object()->TsType();
+    if (objectType != nullptr && !objectType->HasTypeFlag(TypeFlag::ETS_NUMERIC | TypeFlag::CHAR) &&
+        !(objectType->IsETSObjectType() && objectType->AsETSObjectType()->HasObjectFlag(
+                                               ETSObjectFlags::BUILTIN_NUMERIC | ETSObjectFlags::BUILTIN_CHAR))) {
+        return std::nullopt;
+    }
+    auto const &methodName = member->Property()->AsIdentifier()->Name();
+    if (!IsNumericConversion(methodName)) {
+        return std::nullopt;
+    }
+
+    return EvalIntegerConstant(member->Object());
+}
+
+std::optional<int64_t> EvalIntegerConstant(const ir::Expression *expr)
+{
+    if (expr->IsNumberLiteral()) {
+        return EvalIntegerLiteral(expr->AsNumberLiteral());
+    }
+
+    if (expr->IsUnaryExpression()) {
+        return EvalUnaryConstant(expr->AsUnaryExpression());
+    }
+
+    if (expr->IsBinaryExpression()) {
+        return EvalBinaryConstant(expr->AsBinaryExpression());
+    }
+
+    if (expr->IsCallExpression()) {
+        return EvalConversionCall(expr->AsCallExpression());
+    }
+
+    return std::nullopt;
+}
+
+bool IsDirectAssignment(const ir::Expression *node)
+{
+    auto *parent = node->Parent();
+    if (parent == nullptr) {
+        return false;
+    }
+    return parent->IsAssignmentExpression() || parent->IsVariableDeclarator();
+}
+
+std::optional<int64_t> EvalNarrowable(TypeRelation *relation, Type *source, TypeFlag sourceFlags)
+{
+    auto *const checker = relation->GetChecker()->AsETSChecker();
+    auto *const unboxedSource = checker->MaybeUnboxType(source);
+    auto *const node = relation->GetNode();
+    if (node == nullptr) {
+        return std::nullopt;
+    }
+
+    const bool inAssignment = (relation->GetTypeRelationFlags() & TypeRelationFlag::IN_ASSIGNMENT_CONTEXT) != 0;
+    if (!inAssignment || unboxedSource == nullptr || !unboxedSource->HasTypeFlag(sourceFlags)) {
+        return std::nullopt;
+    }
+
+    auto value = EvalIntegerConstant(node);
+    if (!value.has_value()) {
+        return std::nullopt;
+    }
+
+    if (node->IsCallExpression() && !IsDirectAssignment(node)) {
+        return std::nullopt;
+    }
+
+    return value;
+}
+
+bool CheckFitsInTarget(int64_t value, Type *narrowedType)
+{
+    auto flag = static_cast<TypeFlag>(narrowedType->TypeFlags() & TypeFlag::ETS_NUMERIC);
+    switch (flag) {
+        case TypeFlag::BYTE:
+            return FitsIn<int8_t>(value);
+        case TypeFlag::SHORT:
+            return FitsIn<int16_t>(value);
+        case TypeFlag::INT:
+            return FitsIn<int32_t>(value);
+        case TypeFlag::LONG:
+            return FitsIn<int64_t>(value);
+        default:
+            return false;
+    }
+}
+
+void ApplyLiteralNarrowing(ir::NumberLiteral *literal, Type *narrowedType)
+{
+    auto flag = static_cast<TypeFlag>(narrowedType->TypeFlags() & TypeFlag::ETS_NUMERIC);
+    switch (flag) {
+        case TypeFlag::BYTE:
+            literal->Number().TryNarrowTo<int8_t>();
+            break;
+        case TypeFlag::SHORT:
+            literal->Number().TryNarrowTo<int16_t>();
+            break;
+        default:
+            break;
+    }
+}
+
+}  // namespace
+
+NarrowingConverter::NarrowingConverter(ETSChecker *checker, TypeRelation *relation, Type *target, Type *source,
+                                       TypeFlag sources, Type *narrowedType)
+    : TypeConverter(checker, relation, target, source)
+{
+    auto value = EvalNarrowable(relation, source, sources);
+    if (!value.has_value()) {
+        return;
+    }
+    if (!CheckFitsInTarget(value.value(), narrowedType)) {
+        return;
+    }
+    auto *node = relation->GetNode();
+    if (node->IsNumberLiteral()) {
+        ApplyLiteralNarrowing(node->AsNumberLiteral(), narrowedType);
+    }
+    if (!node->IsCallExpression()) {
+        node->SetTsType(narrowedType);
+    }
+    relation->Result(true);
+}
+
+}  // namespace ark::es2panda::checker
